// ai-agents/broker/src/github-pr.ts (sketch): what every agent PR looks like
const REQUESTED_BY = /^Requested-by:\s*@?([A-Za-z0-9-]+)\s*$/m; // the line G0-09's check reads

export const prTitle = (team: "FE" | "BE", key: string, summary: string) => `[${team}] ${key}: ${summary}`;
export const prBranch = (agent: string, key: string) => `${agent}/${key}`; // nova/RH-1234

export const withRequestedBy = (body: string, jiraAccountId: string): string => {
  const person = people.byJiraId(jiraAccountId); // config/people.yaml: Jira accountId to GitHub login
  if (!person) throw new Error(`no GitHub login for ${jiraAccountId}; add them to config/people.yaml`);
  const line = `Requested-by: @${person.github}`;
  if (!REQUESTED_BY.test(line)) throw new Error(`not a GitHub login: ${person.github}`);
  return `${body.trimEnd()}\n\n${line}\n`; // always the last line
};

// ai-agents/broker/src/github-pr.ts (sketch): the broker opens the PR; the VM only asks
export const openDraftPr = async (scope: RunScope, title: string, body: string, requester: string) => {
  const octokit = new Octokit({ auth: await mintToken(scope) }); // 1 hour, one repo, never leaves the broker
  const [owner = "", repo = ""] = scope.repo.split("/");
  const { data: pr } = await octokit.rest.pulls.create({
    owner, repo, base: "main",
    head: scope.branch, // nova/RH-1234: the only branch this run may push
    title, body: withRequestedBy(body, requester),
    draft: true, // always a draft: nobody is pinged yet
  });
  await audit(scope, "pr.create", { number: pr.number }); // every write lands in the audit log
  return { number: pr.number, url: pr.html_url, nodeId: pr.node_id };
};

// ai-agents/orchestrator/src/activities/ready-gate.ts (G4-27): draft to ready only when clean
const DONE = new Set(["fixed", "answered", "with_a_person"]);

export async function readyGate(pr: number, ev: GateEvidence): Promise<GateResult> {
  const checks = await gh<{ name: string; bucket: string }[]>(["pr", "checks", String(pr), "--required", "--json", "name,bucket"]);
  const blockers = checks.filter((c) => c.bucket !== "pass" && c.bucket !== "skipping")
    .map((c) => `CI: ${c.name} is ${c.bucket}`);
  blockers.push(...ev.qa_results.filter((q) => !q.passed).map((q) => `QA check ${q.id} failed`));
  if (ev.scope_judge.verdict === "veto" && !ev.scope_judge.explained) blockers.push("scope judge veto not resolved");
  if (!ev.pr_judge.ready) blockers.push("PR judge: the description has open items");
  const open = ev.findings.filter((f) => f.severity === "important" && !DONE.has(f.state));
  blockers.push(...open.map((f) => `open finding ${f.path}:${f.line}`));
  if (blockers.length) return { ready: false, blockers }; // stays a draft; nobody is pinged
  await gh(["pr", "ready", String(pr)]);
  await gh(["pr", "edit", String(pr), "--add-reviewer", ev.reviewer_team]); // e.g. RhinoHealth/frontend-guild
  return { ready: true, blockers: [] };
}

// ai-agents/broker/src/github-pr.ts (sketch): what `gh pr ready` does. REST cannot leave draft; GraphQL can.
const READY = `mutation($id: ID!) {
  markPullRequestReadyForReview(input: { pullRequestId: $id }) { pullRequest { isDraft url } }
}`;

export const markReady = async (scope: RunScope, pr: { number: number; nodeId: string }) => {
  if (!(await isOwnPr(scope, pr.number))) throw new ScopeDenied("only the run's own PR"); // G3-07
  const octokit = new Octokit({ auth: await mintToken(scope) });
  type Res = { markPullRequestReadyForReview: { pullRequest: { isDraft: boolean } } };
  const res = await octokit.graphql<Res>(READY, { id: pr.nodeId }); // node_id from pulls.create
  return !res.markPullRequestReadyForReview.pullRequest.isDraft; // true: people may now be pinged
};

